/* Booster AI: six prepared Lady voice recordings. No live AI or microphone connection. */
(() => {
  const LIBRARY = {"ar":[{"id":"welcome","question":"من أنتم؟","text":"حياك الله في بوستر. إحنا شركة سعودية نساعد المنشآت تستفيد من الذكاء الاصطناعي في شغلها اليومي.","seconds":6.88,"audio":"data:audio/mpeg;base64,"},{"id":"purpose","question":"وش هدفكم؟","text":"نشخص طريقة العمل. نبني ما يصنع الفرق. نعزز أداء المؤسسة بالذكاء الاصطناعي والتقنية.","seconds":7.68,"audio":"data:audio/mpeg;base64,"},{"id":"help","question":"كيف تساعدوننا؟","text":"نبني لكم مساعدين أذكياء، ونربط أنظمتكم، وَنُنَسِّق خطوات العمل، عشان نساعد فرق المبيعات والمحاسبة وخدمة العملاء ينجزون شغلهم بسهولة.","seconds":11.36,"audio":"data:audio/mpeg;base64,"},{"id":"example","question":"عطيني مثال","text":"تلخيص الاجتماعات ومتابعة المهام، دعم المبيعات والتسويق، تحديد العملاء المناسبين، تجهيز وإرسال عروض الأسعار، الرد على استفسارات العملاء وشكاويهم بالإيميل، إعداد التقارير ودراسات الجدوى، مساندة المحاسبة، ومراجعة العقود واللوائح ورصد المخاطر القانونية المحتملة. وحلول كثيرة غيرها، حسب احتياج منشأتكم.","seconds":23.52,"audio":"data:audio/mpeg;base64,"},{"id":"approach","question":"وش يميز طريقتكم؟","text":"نبدأ بتحليل طريقة شغلكم عشان نختار الحل اللي يناسبكم. ونهتم بأمن معلوماتكم وسريتها، ونحدد صلاحيات الوصول لها. وندرب فريقكم على أدوات الذكاء الاصطناعي، عشان يستخدمونها بثقة ويرفعون جودة شغلهم وإنتاجيتهم.","seconds":16.0,"audio":"data:audio/mpeg;base64,"},{"id":"start","question":"كيف نبدأ؟","text":"عبوا نموذج التواصل، وراح نتواصل معكم وَنُنَسِّق زيارة لِمَقَرِّكُمْ. نسمع منكم ونفهم طريقة شغلكم، ونناقش وين يقدر الذكاء الاصطناعي يفيدكم. بَعْدَهَا نُقَدِّم لكم عرض متكامل يناسب احتياجكم، ويوضح الحل وخطوات التنفيذ والتكلفة.","seconds":17.44,"audio":"data:audio/mpeg;base64,"}],"en":[{"id":"welcome","question":"Who are you?","text":"Welcome to Booster. We are a Saudi company helping organizations use artificial intelligence in their everyday work.","seconds":7.04,"audio":"data:audio/mpeg;base64,"},{"id":"purpose","question":"What is your purpose?","text":"Diagnose the work. Build what matters. Boost the organization with AI and technology.","seconds":6.08,"audio":"data:audio/mpeg;base64,"},{"id":"help","question":"How can you help us?","text":"We build intelligent assistants, connect your systems, and coordinate workflows to help your sales, accounting, and customer service teams get work done more easily.","seconds":8.48,"audio":"data:audio/mpeg;base64,"},{"id":"example","question":"Give me some examples","text":"Meeting summaries and task follow-ups. Sales and marketing support. Finding suitable customers. Preparing and sending quotations. Email responses to customer inquiries and complaints. Reports and feasibility studies. Accounting support. Reviewing contracts and regulations, and flagging potential legal risks. And many more solutions, tailored to your organization.","seconds":22.24,"audio":"data:audio/mpeg;base64,"},{"id":"approach","question":"What makes you different?","text":"We start by analyzing how you work to choose the right solution for you. We focus on information security, confidentiality, and access permissions. We train your team to use AI tools confidently and improve the quality and productivity of their work.","seconds":14.72,"audio":"data:audio/mpeg;base64,"},{"id":"start","question":"How do we get started?","text":"Fill in the contact form. We will get in touch and arrange a visit to your office. We will listen, understand how you work, and explore where AI can help. Then we will prepare a complete proposal tailored to your needs, covering the solution, implementation steps, and cost.","seconds":17.28,"audio":"data:audio/mpeg;base64,"}]};
  const COPY = {
    ar: {label:'دليل بوستر الصوتي',eyebrow:'نشخص. نبني. نعزز.',heading:'تعرف على بوستر',subtitle:'اختر سؤالك واسمع كيف نقدر نساعد منشأتكم.',questions:'أسئلة عن بوستر',close:'إغلاق الدليل',replay:'أعد الاستماع',stop:'إيقاف الصوت',contact:'خلنا نتواصل',footer:'ست إجابات قصيرة عن شركتنا وطريقة عملنا.',launch:'اسمع كيف نساعدك',hint:'تعرف على بوستر بصوتنا',hero:'اسمع كيف نساعد منشأتك',loading:'جار التشغيل…',playing:'تستمع الآن',retry:'اضغط «أعد الاستماع» لتشغيل الصوت.',ended:'اختر سؤالا آخر أو تواصل معنا.',error:'تعذر تشغيل الصوت. تقدر تقرأ الإجابة هنا.',stopped:'تم إيقاف الصوت',resume:'اضغط «أعد الاستماع» للمتابعة.'},
    en: {label:'Booster voice guide',eyebrow:'Diagnose. Build. Boost.',heading:'Meet Booster',subtitle:'Choose a question. Hear how we can help your organization.',questions:'Questions about Booster',close:'Close guide',replay:'Play again',stop:'Stop audio',contact:'Let’s talk',footer:'Six short answers about our company and approach.',launch:'Hear how we can help',hint:'Meet Booster. Press play.',hero:'Hear how we can help',loading:'Starting audio…',playing:'Now playing',retry:'Press “Play again” to hear this answer.',ended:'Choose another question or get in touch.',error:'Audio could not play. You can read the answer here.',stopped:'Audio stopped',resume:'Press “Play again” to continue.'}
  };
  function mount() {
    if (document.getElementById('booster-voice-guide')) return;
    let language=document.documentElement.lang==='en'?'en':'ar';
    let ITEMS=LIBRARY[language],copy=COPY[language];
    const style=document.createElement('style');
    style.textContent=`
      .bv-guide{position:fixed;right:20px;bottom:20px;z-index:60;width:min(370px,calc(100vw - 28px));direction:rtl;font-family:inherit;color:#f4f7ff}
      .bv-panel{padding:20px;background:#071747;border:1px solid #226b70;border-radius:22px;box-shadow:0 16px 55px #0005;margin-bottom:10px;max-height:calc(100dvh - 100px);overflow:auto}
      .bv-guide [hidden]{display:none!important}.bv-top{display:flex;align-items:start;justify-content:space-between;gap:16px}.bv-eyebrow{margin:0 0 5px;color:#56ddbd;font-size:12px}.bv-guide h2{margin:0;font-size:23px}.bv-close{background:none;border:0;color:#c7d7e9;font-size:25px;cursor:pointer;padding:0 6px}.bv-subtitle{font-size:13px;color:#bbc9df;margin:10px 0 16px;line-height:1.6}
      .bv-questions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.bv-question{font:inherit;font-size:13px;min-height:45px;padding:9px;border:1px solid #344767;border-radius:12px;background:#102451;color:#f4f7ff;cursor:pointer;text-align:start}.bv-question:hover,.bv-question[aria-pressed=true]{background:#153e54;border-color:#41d2ae;color:#a7f5da}.bv-guide button:focus-visible,.bv-guide a:focus-visible{outline:3px solid #b9f2e0;outline-offset:3px}
      .bv-answer{margin-top:16px;padding-top:14px;border-top:1px solid #293f61}.bv-title{margin:0 0 6px;color:#56ddbd;font-size:13px}.bv-text{font-size:15px;line-height:1.8;margin:0;min-height:70px}.bv-status{font-size:12px;color:#bdcde2;min-height:19px;margin:8px 0}.bv-actions{display:flex;gap:8px;align-items:center}.bv-control,.bv-contact{font:inherit;font-size:13px;padding:10px 14px;border-radius:10px;text-decoration:none;cursor:pointer}.bv-control{border:1px solid #435573;background:transparent;color:#f4f7ff}.bv-contact{background:#15c69c;color:#062431;border:1px solid #15c69c}.bv-launch{font:inherit;background:#15c69c;color:#062431;border:0;border-radius:30px;padding:14px 21px;font-weight:700;cursor:pointer;box-shadow:0 8px 25px #0003;float:right}.bv-footer{font-size:11px;color:#9fb1cb;margin:14px 0 0}
      .bv-guide[dir=ltr]{direction:ltr}.bv-launch{display:flex;align-items:center;gap:12px;text-align:start;padding:14px 19px;border:2px solid #a5f7dd;animation:bv-pulse 2.8s ease-out 3;transition:transform .2s,box-shadow .2s}.bv-launch:hover{transform:translateY(-3px);box-shadow:0 12px 30px #0004}.bv-launch-copy{display:grid;gap:4px}.bv-launch-title{font-size:16px}.bv-launch-hint{font-size:11px;font-weight:400}.bv-play-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;background:#062431;color:#fff;font-size:16px;flex-shrink:0;direction:ltr}.bv-guide[data-engaged=true] .bv-launch{animation:none}
      [data-voice-demo-open]{display:inline-flex!important;align-items:center;justify-content:center;gap:12px;background:#15c69c!important;color:#062431!important;border:2px solid #a5f7dd!important;box-shadow:0 6px 24px #15c69c45;animation:bv-pulse 2.8s ease-out 3;font-weight:700!important;min-height:54px;padding:12px 22px!important;border-radius:30px!important;cursor:pointer;transition:transform .2s}[data-voice-demo-open]:hover{transform:translateY(-3px)}[data-voice-demo-open]::before{content:'▶';display:grid;place-items:center;background:#062431;color:white;width:30px;height:30px;border-radius:50%;font-size:12px;direction:ltr}[data-voice-demo-open][data-engaged=true]{animation:none}
      @keyframes bv-pulse{0%,75%,100%{box-shadow:0 0 0 0 #15c69c00}25%{box-shadow:0 0 0 10px #15c69c35}}
      @media(prefers-reduced-motion:reduce){.bv-launch,[data-voice-demo-open]{animation:none!important;transition:none!important}.bv-launch:hover,[data-voice-demo-open]:hover{transform:none}}
      @media(max-width:480px){.bv-guide{right:14px;bottom:14px}.bv-panel{padding:16px}.bv-guide h2{font-size:21px}}
    `;
    document.head.append(style);
    const root=document.createElement('aside');root.id='booster-voice-guide';root.className='bv-guide';root.setAttribute('aria-label','دليل بوستر الصوتي');
    root.innerHTML=`<section class="bv-panel" id="bv-panel" aria-labelledby="bv-heading" hidden>
      <div class="bv-top"><div><p class="bv-eyebrow">نشخص. نبني. نعزز.</p><h2 id="bv-heading">تعرف على بوستر</h2></div><button class="bv-close" aria-label="إغلاق الدليل">×</button></div>
      <p class="bv-subtitle">اختر سؤالك واسمع الإجابة بصوت سعودي.</p>
      <div class="bv-questions" aria-label="أسئلة عن بوستر"></div>
      <div class="bv-answer"><p class="bv-title"></p><p class="bv-text"></p><p class="bv-status" aria-live="polite"></p>
      <div class="bv-actions"><button class="bv-control" type="button">أعد الاستماع</button><a class="bv-contact" href="contact.html">خلنا نتواصل</a></div></div>
      <p class="bv-footer">ست إجابات قصيرة عن شركتنا وطريقة عملنا.</p>
    </section><button class="bv-launch" id="voice-demo-btn" type="button" aria-expanded="false" aria-controls="bv-panel"><span class="bv-play-icon" aria-hidden="true">▶</span><span class="bv-launch-copy"><span class="bv-launch-title"></span><span class="bv-launch-hint"></span></span></button>`;
    document.body.append(root);
    const panel=root.querySelector('.bv-panel'),launch=root.querySelector('.bv-launch'),status=root.querySelector('.bv-status'),control=root.querySelector('.bv-control');
    const audio=new Audio();audio.preload='auto';
    let selected=0,playing=false,token=0;
    const buttons=ITEMS.map((item,index)=>{
      const button=document.createElement('button');button.type='button';button.className='bv-question';button.textContent=item.question;button.setAttribute('aria-pressed','false');
      button.addEventListener('click',()=>play(index));root.querySelector('.bv-questions').append(button);return button;
    });
    function stop(){token++;audio.pause();audio.currentTime=0;playing=false;control.textContent=copy.replay;}
    function show(index){selected=index;root.querySelector('.bv-title').textContent=ITEMS[index].question;root.querySelector('.bv-text').textContent=ITEMS[index].text;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
    async function play(index){
      root.dataset.engaged='true';document.querySelectorAll('[data-voice-demo-open]').forEach(button=>button.dataset.engaged='true');
      stop();const request=token;show(index);status.textContent=copy.loading;
      audio.src=ITEMS[index].audio;
      try{await audio.play();if(request!==token)return;playing=true;control.textContent=copy.stop;status.textContent=copy.playing;}
      catch(error){if(request!==token)return;status.textContent=copy.retry;}
    }
    audio.addEventListener('ended',()=>{playing=false;control.textContent=copy.replay;status.textContent=copy.ended;});
    audio.addEventListener('error',()=>{playing=false;control.textContent=copy.replay;status.textContent=copy.error;});
    control.addEventListener('click',()=>{if(playing){stop();status.textContent=copy.stopped;}else play(selected);});
    function close(){stop();panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus();}
    root.querySelector('.bv-close').addEventListener('click',close);
    launch.addEventListener('click',()=>{if(!panel.hidden){close();return;}panel.hidden=false;launch.setAttribute('aria-expanded','true');play(0);});
    root.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){close();event.preventDefault();}});
    document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();status.textContent=copy.resume;}});
    function translate(){
      const next=document.documentElement.lang==='en'?'en':'ar';
      if(next!==language){stop();language=next;ITEMS=LIBRARY[language];copy=COPY[language];status.textContent='';}
      root.setAttribute('dir',language==='en'?'ltr':'rtl');root.setAttribute('lang',language);root.setAttribute('aria-label',copy.label);
      for(const [selector,key] of [['.bv-eyebrow','eyebrow'],['#bv-heading','heading'],['.bv-subtitle','subtitle'],['.bv-contact','contact'],['.bv-footer','footer'],['.bv-launch-title','launch'],['.bv-launch-hint','hint']])root.querySelector(selector).textContent=copy[key];
      root.querySelector('.bv-close').setAttribute('aria-label',copy.close);root.querySelector('.bv-questions').setAttribute('aria-label',copy.questions);
      buttons.forEach((button,index)=>button.textContent=ITEMS[index].question);
      control.textContent=playing?copy.stop:copy.replay;show(selected);
      document.querySelectorAll('[data-voice-demo-open]').forEach(button=>{button.textContent=copy.hero;button.setAttribute('aria-label',copy.hero);});
    }
    translate();
    new MutationObserver(translate).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
